const fs=require('fs');
let raw=fs.readFileSync('/tmp/doctor.json','utf8');
// extract the JSON object portion (strip trailing non-JSON lines)
let depth=0, end=0, started=false;
for(let i=0;i<raw.length;i++){const c=raw[i]; if(c==='{')depth++; if(c==='}'){depth--; if(started&&depth===0){end=i+1;break;}} if(c==='{')started=true;}
const j=JSON.parse(raw.slice(0,end));
console.log('DOCTOR PROFILE:', j.profile, '| STATUS:', j.status);
for(const c of j.checks){
  console.log('  '+String(c.name).padEnd(38), c.status.padEnd(8), c.code||'', (c.message||'').slice(0,90));
}
"
